(() => {
  'use strict';

  const COURSE_STATE_KEY = 'ebgCourseV2State';
  const FORM_STATE_KEY = 'ebgCourseFormsStateV1';
  const PROFILE_KEY = 'ebgCourseV2Profile';
  const DOCUMENT_KEY = 'ebgCourseCertificateDocumentV1';
  const VERIFY_EMAIL = 'lmalinowski@wup-katowice.pl';
  const CERTIFICATE_LOGOS = {
    project: 'data:image/png;base64,',
    eu: 'data:image/png;base64,'
  };
  const MODULE_TITLES = {
    1: 'Edukacja medialna w epoce cyfrowej',
    2: 'Fake news, manipulacja i stronniczość',
    3: 'Krytyczne myślenie i podejmowanie decyzji',
    4: 'Tematy społecznie wrażliwe i wpływ mediów',
    5: 'Odporność informacyjna, dobrostan i zaangażowanie demokratyczne'
  };

  const storage = (() => {
    try {
      const s = window.localStorage;
      const probe = '__ebg_certificate_probe__';
      s.setItem(probe, '1');
      s.removeItem(probe);
      return s;
    } catch {
      const memory = new Map();
      return {
        getItem: key => memory.has(key) ? memory.get(key) : null,
        setItem: (key, value) => memory.set(key, String(value))
      };
    }
  })();

  const read = (key, fallback = {}) => {
    try {
      const parsed = JSON.parse(storage.getItem(key));
      return parsed && typeof parsed === 'object' ? parsed : fallback;
    } catch {
      return fallback;
    }
  };
  const write = (key, value) => storage.setItem(key, JSON.stringify(value));
  const qs = selector => document.querySelector(selector);
  const qsa = selector => [...document.querySelectorAll(selector)];

  const panel = qs('[data-certificate-document]');
  const nameInput = qs('[data-certificate-name]');
  const emailInput = qs('[data-certificate-email]');
  const downloadButton = qs('[data-certificate-download]');
  const mailLink = qs('[data-certificate-mail]');
  const printButton = qs('[data-certificate-print]');
  const helper = qs('[data-certificate-helper]');
  const fallbackLink = qs('[data-certificate-pdf-fallback]');
  const busy = qs('[data-pdf-busy]');
  let activePdfUrl = '';
  let activeFilename = '';
  let lastBuildError = '';
  let lastBuildSuccess = '';

  if (!panel || !nameInput || !emailInput || !downloadButton || !mailLink || !printButton) return;

  function getRequirements() {
    const course = read(COURSE_STATE_KEY, { completed: [] });
    const completed = new Set(Array.isArray(course.completed) ? course.completed : []);
    const forms = { registration: false, pretest: false, finaltest: false, evaluation: false, ...read(FORM_STATE_KEY, {}) };
    const moduleDetails = [];
    let completedModules = 0;
    let completedSections = 0;
    let totalSections = 0;

    for (let module = 1; module <= 5; module += 1) {
      const sections = qsa(`.course-section[data-module-number="${module}"]`);
      const done = sections.filter(section => completed.has(section.dataset.courseSection)).length;
      const total = sections.length;
      const complete = total > 0 && done === total;
      if (complete) completedModules += 1;
      completedSections += done;
      totalSections += total;
      moduleDetails.push({ module, title: MODULE_TITLES[module], done, total, complete });
    }

    const formsDone = ['registration', 'pretest', 'finaltest', 'evaluation'].filter(key => forms[key]).length;
    return {
      forms,
      formsDone,
      completedModules,
      completedSections,
      totalSections,
      moduleDetails,
      eligible: formsDone === 4 && completedModules === 5 && totalSections > 0 && completedSections === totalSections
    };
  }

  function isEmail(value) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/i.test(String(value || '').trim());
  }

  function getProfile() {
    return { name: '', email: '', ...read(PROFILE_KEY, {}) };
  }

  function saveProfile() {
    const current = getProfile();
    const profile = {
      ...current,
      name: nameInput.value.trim(),
      email: emailInput.value.trim()
    };
    write(PROFILE_KEY, profile);
    const workbookName = qs('[data-participant-name]');
    if (workbookName && workbookName.value !== profile.name) workbookName.value = profile.name;
    document.dispatchEvent(new CustomEvent('ebg:profile-updated'));
  }

  function makeDocumentId() {
    const existing = read(DOCUMENT_KEY, {});
    if (existing.id) return existing.id;
    const now = new Date();
    const date = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}`;
    let random = Math.random().toString(36).slice(2, 8).toUpperCase();
    try {
      const bytes = new Uint8Array(4);
      crypto.getRandomValues(bytes);
      random = [...bytes].map(value => value.toString(16).padStart(2, '0')).join('').slice(0, 8).toUpperCase();
    } catch {}
    const id = `EBG-${date}-${random}`;
    write(DOCUMENT_KEY, { id, createdAt: now.toISOString() });
    return id;
  }

  function updateMailLink(name, email, documentId) {
    const subject = `Potwierdzenie ukończenia kursu – ${name || 'uczestnik'}`;
    const body = [
      'Dzień dobry,',
      '',
      'przesyłam potwierdzenie ukończenia części e-learningowej kursu „Media Literacy, Fake News i Krytyczne Myślenie”.',
      'Oświadczam, że ukończyłem wszystkie pięć modułów w 100%, wypełniłem formularz uczestnika, test wstępny, test końcowy oraz ankietę ewaluacyjną.',
      `Adres e-mail użyty w Google Forms: ${email || '[uzupełnij]'}`,
      `Numer dokumentu: ${documentId || '[zostanie nadany po pobraniu PDF]'}`,
      '',
      'Proszę o weryfikację spełnienia warunków otrzymania certyfikatu.',
      '',
      'W załączeniu przesyłam wygenerowany plik PDF.',
      '',
      'Z poważaniem,',
      name || '[imię i nazwisko]'
    ].join('\n');
    mailLink.href = `mailto:${VERIFY_EMAIL}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
  }

  function updateUi() {
    const requirements = getRequirements();
    panel.hidden = !requirements.eligible;
    if (!requirements.eligible) return;

    const profile = getProfile();
    if (document.activeElement !== nameInput && !nameInput.value) nameInput.value = profile.name || '';
    if (document.activeElement !== emailInput && !emailInput.value) emailInput.value = profile.email || '';

    const validName = nameInput.value.trim().length >= 3;
    const validEmail = isEmail(emailInput.value);
    downloadButton.disabled = !(validName && validEmail);
    printButton.disabled = !(validName && validEmail);
    mailLink.classList.toggle('is-disabled', !(validName && validEmail));
    mailLink.setAttribute('aria-disabled', String(!(validName && validEmail)));
    const docState = read(DOCUMENT_KEY, {});
    updateMailLink(nameInput.value.trim(), emailInput.value.trim(), docState.id || '');

    helper.classList.toggle('is-error', Boolean(lastBuildError));
    helper.classList.toggle('is-success', Boolean(lastBuildSuccess) && !lastBuildError);

    if (!validName || !validEmail) {
      lastBuildError = '';
      lastBuildSuccess = '';
      helper.classList.remove('is-error', 'is-success');
      helper.textContent = 'Uzupełnij imię, nazwisko i prawidłowy adres e-mail użyty w Google Forms. Dopiero wtedy przycisk PDF stanie się aktywny.';
    } else if (lastBuildError) {
      helper.textContent = lastBuildError;
    } else if (lastBuildSuccess) {
      helper.textContent = lastBuildSuccess;
    } else if (docState.generatedAt) {
      helper.textContent = `Dokument był wcześniej przygotowany ${new Intl.DateTimeFormat('pl-PL', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(docState.generatedAt))}. Przygotuj go ponownie, aby uzyskać nowy link do pobrania.`;
    } else {
      helper.textContent = `Warunki zostały spełnione. Przygotuj PDF, zapisz go na urządzeniu, a następnie dołącz ręcznie do wiadomości wysyłanej na adres ${VERIFY_EMAIL}.`;
    }
  }

  function roundedRect(ctx, x, y, width, height, radius) {
    const r = Math.min(radius, width / 2, height / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + width, y, x + width, y + height, r);
    ctx.arcTo(x + width, y + height, x, y + height, r);
    ctx.arcTo(x, y + height, x, y, r);
    ctx.arcTo(x, y, x + width, y, r);
    ctx.closePath();
  }

  function wrap(ctx, text, maxWidth) {
    const words = String(text || '').trim().split(/\s+/);
    const lines = [];
    let line = '';
    for (const word of words) {
      const test = line ? `${line} ${word}` : word;
      if (!line || ctx.measureText(test).width <= maxWidth) line = test;
      else { lines.push(line); line = word; }
    }
    if (line) lines.push(line);
    return lines;
  }

  function drawWrapped(ctx, text, x, y, maxWidth, lineHeight, options = {}) {
    ctx.font = `${options.weight || 400} ${options.size || 24}px Arial`;
    ctx.fillStyle = options.color || '#20384a';
    const lines = wrap(ctx, text, maxWidth);
    lines.forEach((line, index) => ctx.fillText(line, x, y + index * lineHeight));
    return y + lines.length * lineHeight;
  }

  function loadImage(src) {
    return new Promise((resolve, reject) => {
      const image = new Image();
      image.onload = () => resolve(image);
      image.onerror = () => reject(new Error(`Nie udało się wczytać grafiki: ${src}`));
      image.src = src;
    });
  }

  async function loadImageSafe(src) {
    try {
      return await loadImage(src);
    } catch (error) {
      console.warn(error);
      return null;
    }
  }

  function drawContain(ctx, image, x, y, width, height) {
    if (!image) return;
    const scale = Math.min(width / image.width, height / image.height);
    const w = image.width * scale;
    const h = image.height * scale;
    ctx.drawImage(image, x + (width - w) / 2, y + (height - h) / 2, w, h);
  }

  function canvasToPdf(canvas) {
    const jpeg = canvas.toDataURL('image/jpeg', 0.94);
    const raw = atob(jpeg.split(',')[1]);
    const imageBytes = new Uint8Array(raw.length);
    for (let i = 0; i < raw.length; i += 1) imageBytes[i] = raw.charCodeAt(i);
    const enc = text => new TextEncoder().encode(text);
    const pageWidth = 595.28;
    const pageHeight = 841.89;
    const stream = `q ${pageWidth} 0 0 ${pageHeight} 0 0 cm /Im1 Do Q`;
    const objects = {
      1: [enc('1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n')],
      2: [enc('2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n')],
      3: [enc(`3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pageWidth} ${pageHeight}] /Resources << /XObject << /Im1 4 0 R >> >> /Contents 5 0 R >>\nendobj\n`)],
      4: [enc(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${canvas.width} /Height ${canvas.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${imageBytes.length} >>\nstream\n`), imageBytes, enc('\nendstream\nendobj\n')],
      5: [enc(`5 0 obj\n<< /Length ${stream.length} >>\nstream\n${stream}\nendstream\nendobj\n`)]
    };
    const chunks = [enc('%PDF-1.4\n')];
    const offsets = new Array(6).fill(0);
    let length = chunks[0].length;
    for (let i = 1; i <= 5; i += 1) {
      offsets[i] = length;
      for (const chunk of objects[i]) { chunks.push(chunk); length += chunk.length; }
    }
    const xrefOffset = length;
    let xref = 'xref\n0 6\n0000000000 65535 f \n';
    for (let i = 1; i <= 5; i += 1) xref += `${String(offsets[i]).padStart(10, '0')} 00000 n \n`;
    xref += `trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;
    chunks.push(enc(xref));
    return new Blob(chunks, { type: 'application/pdf' });
  }

  function prepareDownload(blob, filename) {
    if (activePdfUrl) URL.revokeObjectURL(activePdfUrl);
    activePdfUrl = URL.createObjectURL(blob);
    activeFilename = filename;

    if (fallbackLink) {
      fallbackLink.href = activePdfUrl;
      fallbackLink.download = filename;
      fallbackLink.hidden = false;
      fallbackLink.classList.add('is-ready');
      fallbackLink.textContent = 'PDF jest gotowy – kliknij tutaj, aby zapisać dokument.';
    }

    return activePdfUrl;
  }

  function safeFilename(name) {
    const normalized = String(name || '')
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-|-$/g, '')
      .slice(0, 50) || 'uczestnik';
    return `potwierdzenie-ukonczenia-kursu-${normalized}.pdf`;
  }

  async function writeWithFilePicker(blob, filename) {
    if (typeof window.showSaveFilePicker !== 'function' || !window.isSecureContext) return false;
    try {
      const handle = await window.showSaveFilePicker({
        suggestedName: filename,
        types: [{
          description: 'Dokument PDF',
          accept: { 'application/pdf': ['.pdf'] }
        }]
      });
      const writable = await handle.createWritable();
      await writable.write(blob);
      await writable.close();
      return true;
    } catch (error) {
      if (error?.name === 'AbortError') return null;
      console.warn('Zapis przez systemowe okno nie powiódł się. Udostępniam zwykły link do pobrania.', error);
      return false;
    }
  }

  function showBusy(text) {
    if (!busy) return;
    busy.hidden = false;
    const label = busy.querySelector('[data-pdf-busy-text]');
    if (label) label.textContent = text;
  }

  function hideBusy() {
    if (busy) busy.hidden = true;
  }

  async function buildPdf() {
    const requirements = getRequirements();
    const name = nameInput.value.trim();
    const email = emailInput.value.trim();
    if (!requirements.eligible) {
      helper.textContent = 'PDF można pobrać dopiero po ukończeniu wszystkich modułów i oznaczeniu czterech formularzy jako wykonanych.';
      return;
    }
    if (name.length < 3 || !isEmail(email)) {
      updateUi();
      return;
    }

    saveProfile();
    lastBuildError = '';
    lastBuildSuccess = '';
    if (fallbackLink) {
      fallbackLink.hidden = true;
      fallbackLink.classList.remove('is-ready');
      fallbackLink.removeAttribute('href');
    }
    downloadButton.disabled = true;
    printButton.disabled = true;
    showBusy('Tworzenie potwierdzenia ukończenia części e-learningowej…');

    try {
      const [projectLogo, euLogo] = await Promise.all([
        loadImageSafe(CERTIFICATE_LOGOS.project),
        loadImageSafe(CERTIFICATE_LOGOS.eu)
      ]);
      const documentId = makeDocumentId();
      const now = new Date();
      const dateLong = new Intl.DateTimeFormat('pl-PL', { dateStyle: 'long', timeStyle: 'short' }).format(now);
      const canvas = document.createElement('canvas');
      canvas.width = 1240;
      canvas.height = 1754;
      const ctx = canvas.getContext('2d', { alpha: false });
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#0c4668';
      ctx.fillRect(0, 0, 24, canvas.height);

      drawContain(ctx, projectLogo, 92, 65, 340, 125);
      drawContain(ctx, euLogo, 848, 60, 290, 135);
      ctx.strokeStyle = '#d4e0e7';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(92, 212);
      ctx.lineTo(1148, 212);
      ctx.stroke();

      ctx.fillStyle = '#19769a';
      ctx.font = '700 22px Arial';
      ctx.fillText('EDUKACJA BEZ GRANIC · KURS ONLINE', 92, 272);
      ctx.fillStyle = '#153b56';
      ctx.font = '700 46px Arial';
      ctx.fillText('Potwierdzenie ukończenia', 92, 338);
      ctx.fillText('części e-learningowej', 92, 394);
      ctx.fillStyle = '#5a7281';
      ctx.font = '400 22px Arial';
      ctx.fillText('Media Literacy, Fake News i Krytyczne Myślenie', 92, 438);

      ctx.fillStyle = '#eaf4f7';
      roundedRect(ctx, 92, 484, 1056, 186, 18);
      ctx.fill();
      ctx.fillStyle = '#0f4666';
      ctx.font = '700 24px Arial';
      ctx.fillText('Uczestnik', 126, 535);
      ctx.font = '400 30px Arial';
      ctx.fillText(name, 126, 581);
      ctx.font = '700 20px Arial';
      ctx.fillText('Adres e-mail użyty w Google Forms', 126, 624);
      ctx.font = '400 22px Arial';
      ctx.fillText(email, 478, 624);
      ctx.textAlign = 'right';
      ctx.fillStyle = '#14789e';
      ctx.font = '700 48px Arial';
      ctx.fillText('100%', 1112, 558);
      ctx.font = '700 18px Arial';
      ctx.fillText('UKOŃCZENIA KURSU', 1112, 593);
      ctx.textAlign = 'left';

      ctx.fillStyle = '#153b56';
      ctx.font = '700 26px Arial';
      ctx.fillText('Ukończone moduły', 92, 735);
      let y = 786;
      requirements.moduleDetails.forEach(item => {
        ctx.fillStyle = '#f5f8fa';
        roundedRect(ctx, 92, y - 32, 1056, 64, 12);
        ctx.fill();
        ctx.fillStyle = '#1d789b';
        ctx.beginPath();
        ctx.arc(124, y, 13, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#ffffff';
        ctx.font = '700 16px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('✓', 124, y + 6);
        ctx.textAlign = 'left';
        ctx.fillStyle = '#203e52';
        ctx.font = '700 21px Arial';
        ctx.fillText(`Moduł ${item.module}. ${item.title}`, 156, y + 6);
        ctx.textAlign = 'right';
        ctx.fillStyle = '#28785f';
        ctx.font = '700 19px Arial';
        ctx.fillText(`${item.done}/${item.total} · 100%`, 1112, y + 6);
        ctx.textAlign = 'left';
        y += 76;
      });

      ctx.fillStyle = '#153b56';
      ctx.font = '700 26px Arial';
      ctx.fillText('Oświadczenia uczestnika', 92, 1190);
      const statements = [
        `Ukończyłem wszystkie pięć modułów kursu – ${requirements.completedSections} z ${requirements.totalSections} tematów, czyli 100%.`,
        'Wypełniłem formularz uczestnika oraz test wstępny w Google Forms.',
        'Wypełniłem test końcowy. Wynik testu podlega weryfikacji przez organizatora.',
        'Wypełniłem ankietę ewaluacyjną i we wszystkich formularzach użyłem wskazanego wyżej adresu e-mail.'
      ];
      y = 1242;
      ctx.font = '400 21px Arial';
      statements.forEach((statement, index) => {
        ctx.fillStyle = '#14789e';
        ctx.beginPath();
        ctx.arc(107, y - 7, 7, 0, Math.PI * 2);
        ctx.fill();
        y = drawWrapped(ctx, statement, 132, y, 982, 29, { size: 21, color: '#29485b' }) + 16;
      });

      ctx.fillStyle = '#fff4dc';
      roundedRect(ctx, 92, 1450, 1056, 125, 16);
      ctx.fill();
      ctx.fillStyle = '#724f12';
      ctx.font = '700 21px Arial';
      ctx.fillText('Dokument nie jest certyfikatem.', 122, 1495);
      drawWrapped(ctx, `Prześlij plik do weryfikacji na adres ${VERIFY_EMAIL}. Certyfikat zostanie wystawiony po sprawdzeniu danych w Google Forms, wyniku testu końcowego i ukończenia kursu.`, 122, 1530, 980, 27, { size: 19, color: '#6a531f' });

      ctx.strokeStyle = '#d4e0e7';
      ctx.beginPath();
      ctx.moveTo(92, 1632);
      ctx.lineTo(1148, 1632);
      ctx.stroke();
      ctx.fillStyle = '#577080';
      ctx.font = '400 17px Arial';
      ctx.fillText(`Data wygenerowania: ${dateLong}`, 92, 1672);
      ctx.fillText(`Numer dokumentu: ${documentId}`, 92, 1705);
      ctx.textAlign = 'right';
      ctx.fillText('Wojewódzki Urząd Pracy w Katowicach', 1148, 1672);
      ctx.fillText('Projekt „Edukacja bez granic” · 2026', 1148, 1705);
      ctx.textAlign = 'left';

      const blob = canvasToPdf(canvas);
      const filename = safeFilename(name);
      prepareDownload(blob, filename);
      const savedWithPicker = await writeWithFilePicker(blob, filename);
      write(DOCUMENT_KEY, { id: documentId, generatedAt: now.toISOString(), name, email });
      updateMailLink(name, email, documentId);

      if (savedWithPicker === true) {
        lastBuildSuccess = `PDF został zapisany na urządzeniu. Poniższy link pozostaje dostępny, gdy chcesz pobrać dokument ponownie. Następnie dołącz plik do wiadomości wysyłanej na adres ${VERIFY_EMAIL}.`;
      } else if (savedWithPicker === null) {
        lastBuildSuccess = 'Anulowano systemowe okno zapisu. Dokument został przygotowany – użyj widocznego poniżej przycisku, aby pobrać PDF.';
      } else {
        lastBuildSuccess = `Dokument został przygotowany. Kliknij widoczny poniżej przycisk „PDF jest gotowy”, aby zapisać plik, a następnie dołącz go do wiadomości wysyłanej na adres ${VERIFY_EMAIL}.`;
      }
      downloadButton.textContent = 'Przygotuj PDF ponownie';
      fallbackLink?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      fallbackLink?.focus({ preventScroll: true });
    } catch (error) {
      console.error('Błąd tworzenia potwierdzenia PDF:', error);
      const reason = error && error.message ? ` Szczegóły: ${error.message}` : '';
      lastBuildError = `Nie udało się utworzyć PDF.${reason} Użyj przycisku „Otwórz wersję do druku / zapisu jako PDF” albo odśwież stronę i spróbuj ponownie.`;
    } finally {
      hideBusy();
      updateUi();
    }

  }

  function escapeHtml(value) {
    return String(value || '').replace(/[&<>"']/g, character => ({
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#39;'
    }[character]));
  }

  function openPrintVersion() {
    const requirements = getRequirements();
    const name = nameInput.value.trim();
    const email = emailInput.value.trim();
    if (!requirements.eligible || name.length < 3 || !isEmail(email)) {
      updateUi();
      return;
    }

    saveProfile();
    const documentId = makeDocumentId();
    const generated = new Intl.DateTimeFormat('pl-PL', { dateStyle: 'long', timeStyle: 'short' }).format(new Date());
    const projectLogo = CERTIFICATE_LOGOS.project;
    const euLogo = CERTIFICATE_LOGOS.eu;
    const moduleRows = requirements.moduleDetails.map(item => `
      <tr><td>Moduł ${item.module}. ${escapeHtml(item.title)}</td><td>${item.done}/${item.total}</td><td>100%</td></tr>`).join('');
    const popup = window.open('', '_blank');
    if (!popup) {
      lastBuildError = 'Przeglądarka zablokowała okno wersji do druku. Zezwól tej stronie na otwieranie nowych okien i spróbuj ponownie.';
      lastBuildSuccess = '';
      updateUi();
      return;
    }
    popup.document.open();
    popup.document.write(`<!doctype html><html lang="pl"><head><meta charset="utf-8"><title>Potwierdzenie ukończenia części e-learningowej</title><style>
      @page{size:A4;margin:16mm}*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;color:#183b52;background:#fff;line-height:1.45}.page{border-left:7px solid #0c4668;padding:0 0 0 20px}.logos{display:flex;justify-content:space-between;align-items:center;gap:24px;border-bottom:1px solid #cfdde5;padding-bottom:14px}.logos img{max-width:240px;max-height:72px;object-fit:contain}.kicker{margin:28px 0 8px;color:#19769a;font-weight:700;letter-spacing:.08em}.title{margin:0;font-size:30px;line-height:1.15}.subtitle{margin:8px 0 24px;color:#587080}.person{display:grid;grid-template-columns:1fr auto;gap:20px;padding:18px 20px;border-radius:12px;background:#eaf4f7}.person h2{margin:0 0 8px;font-size:21px}.person p{margin:4px 0}.score{align-self:center;font-size:34px;font-weight:700;color:#14789e}.score small{display:block;font-size:12px;letter-spacing:.06em}.section-title{margin:28px 0 12px;font-size:19px}.modules{width:100%;border-collapse:collapse}.modules td{padding:10px 12px;border-bottom:1px solid #dae4ea}.modules td:nth-child(2),.modules td:nth-child(3){text-align:right;font-weight:700}.statements{padding-left:20px}.statements li{margin:8px 0}.notice{margin-top:24px;padding:14px 16px;border-radius:10px;background:#fff4dc;color:#674c1d}.footer{display:flex;justify-content:space-between;gap:20px;margin-top:28px;padding-top:12px;border-top:1px solid #cfdde5;color:#587080;font-size:12px}.actions{margin:18px 0;padding:12px;background:#f1f5f7;text-align:center}.actions button{padding:10px 16px;border:0;border-radius:8px;background:#166b91;color:#fff;font-weight:700;cursor:pointer}@media print{.actions{display:none}.page{border-left:5px solid #0c4668}.logos img{max-width:210px}}
    </style></head><body><div class="actions"><button onclick="window.print()">Drukuj lub zapisz jako PDF</button></div><main class="page"><div class="logos"><img src="${projectLogo}" alt="Edukacja bez granic"><img src="${euLogo}" alt="Dofinansowane przez Unię Europejską"></div><p class="kicker">EDUKACJA BEZ GRANIC · KURS ONLINE</p><h1 class="title">Potwierdzenie ukończenia części e-learningowej</h1><p class="subtitle">Media Literacy, Fake News i Krytyczne Myślenie</p><section class="person"><div><h2>${escapeHtml(name)}</h2><p>${escapeHtml(email)}</p></div><div class="score">100%<small>UKOŃCZENIA KURSU</small></div></section><h2 class="section-title">Ukończone moduły</h2><table class="modules"><tbody>${moduleRows}</tbody></table><h2 class="section-title">Oświadczenia uczestnika</h2><ul class="statements"><li>Ukończyłem wszystkie pięć modułów kursu – ${requirements.completedSections} z ${requirements.totalSections} tematów, czyli 100%.</li><li>Wypełniłem formularz uczestnika oraz test wstępny w Google Forms.</li><li>Wypełniłem test końcowy. Wynik testu podlega weryfikacji przez organizatora.</li><li>Wypełniłem ankietę ewaluacyjną i we wszystkich formularzach użyłem wskazanego wyżej adresu e-mail.</li></ul><div class="notice"><strong>Dokument nie jest certyfikatem.</strong><br>Prześlij go do weryfikacji na adres ${VERIFY_EMAIL}. Certyfikat zostanie wystawiony po sprawdzeniu danych w Google Forms, wyniku testu końcowego i ukończenia kursu.</div><footer class="footer"><div>Data wygenerowania: ${generated}<br>Numer dokumentu: ${documentId}</div><div>Wojewódzki Urząd Pracy w Katowicach<br>Projekt „Edukacja bez granic” · 2026</div></footer></main><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),500));<\/script></body></html>`);
    popup.document.close();
    lastBuildSuccess = 'Otworzono wersję do druku. W oknie drukowania wybierz „Zapisz jako PDF”, aby zapisać dokument na urządzeniu.';
    lastBuildError = '';
    updateUi();
  }

  const initialProfile = getProfile();
  nameInput.value = initialProfile.name || '';
  emailInput.value = initialProfile.email || '';

  nameInput.addEventListener('input', () => { saveProfile(); updateUi(); });
  emailInput.addEventListener('input', () => { saveProfile(); updateUi(); });
  qs('[data-participant-name]')?.addEventListener('input', event => {
    if (document.activeElement !== nameInput) nameInput.value = event.currentTarget.value;
    updateUi();
  });
  downloadButton.addEventListener('click', buildPdf);
  printButton.addEventListener('click', openPrintVersion);
  mailLink.addEventListener('click', event => {
    if (mailLink.getAttribute('aria-disabled') === 'true') event.preventDefault();
  });

  document.addEventListener('ebg:certificate-requirements-updated', updateUi);
  document.addEventListener('ebg:course-progress-updated', () => setTimeout(updateUi, 0));
  document.addEventListener('ebg:profile-updated', () => setTimeout(updateUi, 0));
  document.addEventListener('change', event => {
    if (event.target.closest('[data-form-complete]')) setTimeout(updateUi, 0);
  });
  window.addEventListener('storage', event => {
    if ([COURSE_STATE_KEY, FORM_STATE_KEY, PROFILE_KEY, DOCUMENT_KEY].includes(event.key)) updateUi();
  });
  window.addEventListener('beforeunload', () => {
    if (activePdfUrl) URL.revokeObjectURL(activePdfUrl);
  });

  updateUi();
})();
